  ('143b9088-6361-42ce-9b49-66099a725241', 'b6e1d4a8-2c39-4f07-9b52-8a0e5c3d7f16', null, 'topic'::public.curated_course_node_type, 'Course Orientation, Global Health Concepts, and Historical Foundations', 'This opening unit defines global health as a field concerned with health improvement, equity, cross-border determinants, and transnational cooperation. Students learn the vocabulary and history needed to interpret later debates.', 0),
  ('69daaf3e-fc67-4bd6-8b69-8d26636b5d3c', 'b6e1d4a8-2c39-4f07-9b52-8a0e5c3d7f16', '143b9088-6361-42ce-9b49-66099a725241', 'subtopic'::public.curated_course_node_type, 'What Global Health Means', 'Students learn how global health differs from international health and public health while overlapping with both.', 0),
