  ('5b4af82e-89c3-406d-8429-302612a0145b', 'b6e1d4a8-2c39-4f07-9b52-8a0e5c3d7f16', '061e3fad-f872-459a-88af-ea1e26b4be81', 'concept'::public.curated_course_node_type, 'WHO Global Health Observatory', null, 0),
