  ('c3a3e538-d603-48d0-893c-5f58f6f7d48c', 'b6e1d4a8-2c39-4f07-9b52-8a0e5c3d7f16', '2df83eac-d978-4864-bdf4-8714003ef2ab', 'concept'::public.curated_course_node_type, 'Neonatal complications', null, 0),
